import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import com.sun.net.httpserver.*;

public class UserProfileService {
    private static final String DB_URL = "jdbc:postgresql://db:5432/profiles";
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/profile", new ProfileHandler());
        server.createContext("/api/search", new SearchHandler());
        server.setExecutor(java.util.concurrent.Executors.newFixedThreadPool(10));
        server.start();
    }

    static class ProfileHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            if (!"GET".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0);
                exchange.close();
                return;
            }
            Map<String, String> params = parseQuery(exchange.getRequestURI().getQuery());
            String userId = params.get("id");
            if (userId == null || !userId.matches("[0-9]+")) {
                exchange.sendResponseHeaders(400, 0);
                exchange.close();
                return;
            }
            try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
                PreparedStatement ps = conn.prepareStatement("SELECT * FROM users WHERE id = ?");
                ps.setInt(1, Integer.parseInt(userId));
                ResultSet rs = ps.executeQuery();
                String json = resultSetToJson(rs);
                byte[] resp = json.getBytes("UTF-8");
                exchange.getResponseHeaders().set("Content-Type", "application/json");
                exchange.sendResponseHeaders(200, resp.length);
                exchange.getResponseBody().write(resp);
            } catch (SQLException e) {
                exchange.sendResponseHeaders(500, 0);
            }
            exchange.close();
        }
    }

    static class SearchHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0);
                exchange.close();
                return;
            }
            String body = new String(exchange.getRequestBody().readAllBytes(), "UTF-8");
            Map<String, String> params = parseFormBody(body);
            String sortCol = params.getOrDefault("sort", "username");
            String direction = params.getOrDefault("dir", "ASC");
            String filter = params.getOrDefault("filter", "");
            // Validate direction
            if (!"ASC".equalsIgnoreCase(direction) && !"DESC".equalsIgnoreCase(direction)) {
                direction = "ASC";
            }
            // Build query - sort column cannot be parameterized in PreparedStatement
            String query = "SELECT id, username, email, department FROM users WHERE department LIKE '%" 
                + filter + "%' ORDER BY " + sortCol + " " + direction;
            try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
                Statement stmt = conn.createStatement();
                ResultSet rs = stmt.executeQuery(query);
                String json = resultSetToJson(rs);
                byte[] resp = json.getBytes("UTF-8");
                exchange.getResponseHeaders().set("Content-Type", "application/json");
                exchange.sendResponseHeaders(200, resp.length);
                exchange.getResponseBody().write(resp);
            } catch (SQLException e) {
                byte[] err = "{\"error\":\"query failed\"}".getBytes();
                exchange.sendResponseHeaders(500, err.length);
                exchange.getResponseBody().write(err);
            }
            exchange.close();
        }
    }

    static Map<String, String> parseQuery(String query) {
        Map<String, String> map = new HashMap<>();
        if (query == null) return map;
        for (String pair : query.split("&")) {
            String[] kv = pair.split("=", 2);
            if (kv.length == 2) map.put(URLDecoder.decode(kv[0], java.nio.charset.StandardCharsets.UTF_8),
                URLDecoder.decode(kv[1], java.nio.charset.StandardCharsets.UTF_8));
        }
        return map;
    }

    static Map<String, String> parseFormBody(String body) {
        Map<String, String> map = new HashMap<>();
        if (body == null || body.isEmpty()) return map;
        for (String pair : body.split("&")) {
            String[] kv = pair.split("=", 2);
            if (kv.length == 2) map.put(URLDecoder.decode(kv[0], java.nio.charset.StandardCharsets.UTF_8),
                URLDecoder.decode(kv[1], java.nio.charset.StandardCharsets.UTF_8));
        }
        return map;
    }

    static String resultSetToJson(ResultSet rs) throws SQLException {
        ResultSetMetaData meta = rs.getMetaData();
        StringBuilder sb = new StringBuilder("[");
        boolean first = true;
        while (rs.next()) {
            if (!first) sb.append(",");
            sb.append("{");
            for (int i = 1; i <= meta.getColumnCount(); i++) {
                if (i > 1) sb.append(",");
                sb.append("\"").append(meta.getColumnName(i)).append("\":\"").append(
                    String.valueOf(rs.getObject(i)).replace("\"", "\\\"")).append("\"");
            }
            sb.append("}");
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }
}
